import { chromium } from '@playwright/test'
const b=await chromium.launch({executablePath:'C:/Users/Administrator/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe'})
const pg=await b.newPage({viewport:{width:390,height:844}})
await pg.goto('http://127.0.0.1:8099/#/pages/detail/index?id=QY-20260718-0003&kind=rescue',{waitUntil:'domcontentloaded',timeout:25000}).catch(()=>{})
await pg.waitForTimeout(2500)
const info=await pg.evaluate(()=>{
  const head=document.querySelector('.timeline-head')
  const bEl=head?head.querySelector('b'):null
  const time=head?head.querySelector('time'):null
  const p=document.querySelector('.timeline-item p')
  function r(el){if(!el)return null;const b=el.getBoundingClientRect();return {top:Math.round(b.top),left:Math.round(b.left),right:Math.round(b.right),w:Math.round(b.width),h:Math.round(b.height)}}
  return { head:r(head), title:r(bEl), time:r(time), p:r(p),
    titleAndTimeSameLine: (bEl&&time)? Math.abs(bEl.getBoundingClientRect().top - time.getBoundingClientRect().top) < 5 : null,
    pBelowHead: (head&&p)? p.getBoundingClientRect().top >= head.getBoundingClientRect().bottom-2 : null }
})
console.log(JSON.stringify(info,null,2))
await pg.evaluate(()=>{const t=document.querySelector('.timeline'); if(t) t.scrollIntoView({block:'center'})})
await pg.waitForTimeout(300)
await pg.screenshot({path:'D:/repository/_tl.png'})
await b.close()

